  "예상 혼잡은 서울시 실시간 도시데이터와 CrowdView 예측이에요. 이동시간은 서울시 지하철 역간 소요시간과 걷는 거리로 어림한 값이라 실제와 다를 수 있어요. 식사는 서울 여행 가이드 맛집 중 가까운 곳이에요.":
    [
      "Expected crowds come from Seoul real-time city data and CrowdView forecasts. Travel times are estimated from Seoul subway station-to-station times plus walking, and may differ. Meals are nearby picks from the Seoul travel guide.",
      "予想混雑はソウル市リアルタイム都市データとCrowdViewの予測です。移動時間はソウル市地下鉄の駅間所要時間と徒歩距離による概算で、実際と異なる場合があります。食事はソウル旅行ガイドのグルメから近い店です。",
      "预计拥挤度来自首尔市实时城市数据和CrowdView预测。移动时间按首尔地铁站间所需时间和步行距离估算，可能与实际不同。用餐地点是首尔旅行指南中附近的美食。",
      "預計擁擠度來自首爾市即時城市資料和CrowdView預測。移動時間依首爾地鐵站間所需時間和步行距離估算，可能與實際不同。用餐地點是首爾旅遊指南中附近的美食。",
    ],
