  "날마다 운영 시간 색 띠 · 띠를 누르거나 밀면 그 시간 예상 인원": ["One color strip per day · tap or slide for that hour's expected crowd","日ごとの色帯・タップまたはスライドでその時間の予想人数","每天一条色带 · 点击或滑动查看该时段预计人数","每天一條色帶 · 點擊或滑動查看該時段預計人數"],
  "날마다 운영 시간 색 띠 · 띠를 누르거나 밀면 그 시간 예상 혼잡": ["One color strip per day · tap or slide for that hour's expected crowd level","日ごとの色帯・タップまたはスライドでその時間の予想混雑","每天一条色带 · 点击或滑动查看该时段预计拥挤","每天一條色帶 · 點擊或滑動查看該時段預計擁擠"],
  "하루 중 가장 붐빌 때 · 막대를 누르거나 밀어 보세요": ["Busiest time of each day · tap or slide the bars","1日で最も混む時間・棒をタップまたはスライド","每天最拥挤时段 · 点击或滑动柱状图","每天最擁擠時段 · 點擊或滑動長條圖"],
  "{calm}요일이 가장 한산하고, {busy}요일이 가장 붐벼요.": ["{calm} is the quietest and {busy} the busiest.","{calm}曜日が一番すいていて、{busy}曜日が一番混みます。","{calm}最空闲，{busy}最拥挤。","{calm}最空閒，{busy}最擁擠。"],
