  // 2026-10-20: Plus 1개월 이용권
  "부가세 포함 · 1개월 이용권 또는 매달 자동결제": ["VAT incl. · 1-month pass or monthly auto-renewal","税込・1か月パスまたは毎月自動決済","含增值税 · 1个月通行证或每月自动扣款","含營業稅 · 1個月通行證或每月自動扣款"],
  "이용 기간: 결제한 날부터 1개월 (자동결제를 고르면 매달 같은 날 갱신)": ["Period: 1 month from payment (auto-renewal renews on the same day each month)","利用期間：決済日から1か月（自動決済を選ぶと毎月同じ日に更新）","使用期限：自付款日起1个月（选择自动扣款则每月同日续费）","使用期限：自付款日起1個月（選擇自動扣款則每月同日續費）"],
  "1개월 이용권은 {price}원을 한 번만 결제하고, 자동으로 다시 결제되지 않아요.": ["The 1-month pass is a single payment of ₩{price} and does not renew automatically.","1か月パスは{price}ウォンを1回だけ決済し、自動で再決済されません。","1个月通行证只支付一次{price}韩元，不会自动续费。","1個月通行證只支付一次{price}韓元，不會自動續費。"],
  "매달 자동결제는 결제한 날부터 1개월마다 같은 날 {price}원이 결제돼요.": ["Monthly auto-renewal charges ₩{price} on the same day every month.","毎月自動決済は決済日から毎月同じ日に{price}ウォンが決済されます。","每月自动扣款将在每月同一天扣款{price}韩元。","每月自動扣款將在每月同一天扣款{price}韓元。"],
  "자동결제는 마이페이지에서 언제든 해지할 수 있고, 해지해도 남은 기간은 계속 쓸 수 있어요.": ["You can cancel auto-renewal anytime in My Page and keep using the remaining period.","自動決済はマイページでいつでも解約でき、残りの期間は引き続き使えます。","可随时在我的页面取消自动扣款，剩余期限可继续使用。","可隨時在我的頁面取消自動扣款，剩餘期限可繼續使用。"],
  "1개월 이용권 결제 ({price}원)": ["Buy 1-month pass (₩{price})","1か月パスを購入（{price}ウォン）","购买1个月通行证（{price}韩元）","購買1個月通行證（{price}韓元）"],
  "매달 자동결제로 시작": ["Start with monthly auto-renewal","毎月自動決済で始める","以每月自动扣款开始","以每月自動扣款開始"],
  "{name} 1개월 이용권": ["{name} 1-month pass","{name} 1か月パス","{name} 1个月通行证","{name} 1個月通行證"],
  "{price}원 (부가세 포함), 한 번만 결제돼요": ["₩{price} (VAT incl.), charged once","{price}ウォン（税込）、1回だけ決済されます","{price}韩元（含税），仅扣款一次","{price}韓元（含稅），僅扣款一次"],
  "이용 기간: 결제한 날부터 1개월": ["Period: 1 month from payment","利用期間：決済日から1か月","使用期限：自付款日起1个月","使用期限：自付款日起1個月"],
  "자동으로 다시 결제되지 않아요. 끝날 때 마이페이지에서 1개월 더 이어서 결제할 수 있어요": ["It won't renew automatically. You can add another month from My Page.","自動で再決済されません。終わるときにマイページから1か月追加できます","不会自动续费。到期时可在我的页面再续1个月","不會自動續費。到期時可在我的頁面再續1個月"],
  "위 내용을 확인했고, 결제에 동의해요": ["I've read the above and agree to pay","上記を確認し、決済に同意します","已确认以上内容并同意付款","已確認以上內容並同意付款"],
  "결제하기": ["Pay","決済する","付款","付款"],
  "1개월 이용권 ({date}까지)": ["1-month pass (until {date})","1か月パス（{date}まで）","1个月通行证（至{date}）","1個月通行證（至{date}）"],
  "1개월 더 이어서 결제": ["Add another month","1か月延長して決済","再续1个月","再續1個月"],
  "부가세 포함 · 1개월 이용권 (한 번 결제, 자동 갱신 없음)": ["VAT incl. · 1-month pass (single payment, no auto-renewal)","税込・1か月パス（1回決済、自動更新なし）","含增值税 · 1个月通行证（单次付款，不自动续费）","含營業稅 · 1個月通行證（單次付款，不自動續費）"],
  "이용 중에 다시 결제하면 남은 기간 뒤로 1개월이 더해져요.": ["Paying again while active adds 1 month after your remaining period.","利用中に再度決済すると、残り期間の後に1か月が追加されます。","使用期间再次付款，将在剩余期限后再加1个月。","使用期間再次付款，將在剩餘期限後再加1個月。"],
