  "전체 시간표 · 붐비면 다시 짜기 · 1개월 3,900원": ["Full schedule · re-plan when crowded · ₩3,900 for 1 month","全日程・混んだら再作成・1か月3,900ウォン","完整行程 · 拥挤时重新规划 · 1个月3,900韩元","完整行程 · 擁擠時重新規劃 · 1個月3,900韓元"],
