  "비 와도 좋은 실내 모음": ["Indoor spots for rainy days", "雨でも楽しい屋内スポット", "下雨也好玩的室内景点", "下雨也好玩的室內景點"],
  "거리·명소": ["Streets·Sights", "通り・名所", "街道·景点", "街道·景點"],
