  "스키장 미리 보는 혼잡 모음": ["Ski resorts: crowd preview", "スキー場の混雑を先読み", "滑雪场拥挤预览", "滑雪場擁擠預覽"],
  "테마별 한산한 곳 모음": ["Quiet spots by theme", "テーマ別・空いている場所", "按主题看人少的地方", "按主題看人少的地方"],
  "테마를 고르면 지금 덜 붐비는 곳 3곳": ["Pick a theme to see 3 quieter spots now", "テーマを選ぶと今空いている3か所", "选择主题，查看现在人少的3处", "選擇主題，查看現在人少的3處"],

  "한 달": ["Month", "1か月", "一个月", "一個月"],
  "앞으로 5주, 날마다 가장 붐빌 때의 예상 단계예요. 날짜를 누르면 그날 이유가 보여요": ["Next 5 weeks: each day's expected peak level. Tap a date for the reasons", "今後5週間、日ごとの最も混む時間の予想段階です。日付をタップすると理由が表示されます", "未来5周每天最拥挤时段的预计等级。点日期查看原因", "未來5週每天最擁擠時段的預計等級。點日期查看原因"],
  "앞으로 1년 중 {month}이 가장 한산해요": ["{month} is the quietest month in the next year", "今後1年で{month}が最も空いています", "未来一年中{month}最清闲", "未來一年中{month}最清閒"],
