  "새해 복 많이 받으세요!": ["Happy New Year!","あけましておめでとうございます！","新年快乐！","新年快樂！"],
  "올해도 한산한 곳으로 안내할게요": ["We'll keep guiding you to quiet spots this year","今年も空いている場所へご案内します","今年也带你去清静的地方","今年也帶你去清靜的地方"],
  "설 연휴, 가족과 따뜻하게 보내세요": ["Happy Seollal (Lunar New Year)!","ソルラル（旧正月）、ご家族と温かくお過ごしください","春节（韩国新年）快乐，与家人温暖相聚","春節（韓國新年）快樂，與家人溫暖相聚"],
  "고궁·민속촌 설 행사와 귀성길 혼잡을 확인하세요": ["Check palace & folk village New Year events and holiday traffic","古宮・民俗村の旧正月イベントと帰省ラッシュをチェック","查看古宫、民俗村新年活动与返乡拥堵","查看古宮、民俗村新年活動與返鄉擁堵"],
  "3·1절, 그날의 함성을 기억해요": ["March 1st Independence Movement Day","三・一節、あの日の叫びを忘れずに","三一节，铭记那天的呐喊","三一節，銘記那天的吶喊"],
  "독립기념관·서대문형무소역사관도 둘러보세요": ["Visit the Independence Hall or Seodaemun Prison History Hall","独立記念館・西大門刑務所歴史館もどうぞ","也去看看独立纪念馆、西大门刑务所历史馆","也去看看獨立紀念館、西大門刑務所歷史館"],
  "어린이날, 마음껏 뛰어놀아요!": ["Happy Children's Day!","こどもの日、思いきり遊ぼう！","儿童节快乐，尽情玩耍吧！","兒童節快樂，盡情玩耍吧！"],
  "놀이공원·테마파크 혼잡을 미리 보고 가세요": ["Check amusement park crowds before you go","遊園地・テーマパークの混雑を事前にチェック","出发前先看游乐园、主题公园拥挤度","出發前先看遊樂園、主題公園擁擠度"],
  "광복절, 빛을 되찾은 날": ["Liberation Day — the day light returned","光復節、光を取り戻した日","光复节，重获光明的日子","光復節，重獲光明的日子"],
  "태극기 달고 의미 있는 하루 보내세요": ["Have a meaningful day","意義ある一日をお過ごしください","度过有意义的一天","度過有意義的一天"],
  "풍성한 한가위 보내세요": ["Happy Chuseok!","豊かなチュソク（秋夕）をお過ごしください","中秋（秋夕）快乐，阖家团圆","中秋（秋夕）快樂，闔家團圓"],
  "고궁 한가위 행사와 연휴 혼잡을 미리 확인하세요": ["Check palace Chuseok events and holiday crowds ahead","古宮のチュソク行事と連休の混雑を事前にチェック","提前查看古宫中秋活动与假期拥挤","提前查看古宮中秋活動與假期擁擠"],
  "개천절, 하늘이 열린 날": ["National Foundation Day","開天節、天が開かれた日","开天节，天开之日","開天節，天開之日"],
  "가을 하늘 아래 한산한 명소로 떠나 보세요": ["Head to a quiet spot under the autumn sky","秋空の下、空いている名所へ出かけましょう","在秋日晴空下去清静的名胜走走","在秋日晴空下去清靜的名勝走走"],
  "한글날, 우리 글을 기려요": ["Hangeul Day — celebrating the Korean alphabet","ハングルの日、韓国の文字を祝おう","韩文日，纪念韩国文字","韓文日，紀念韓國文字"],
  "국립한글박물관·세종대왕 동상도 둘러보세요": ["Visit the National Hangeul Museum or the King Sejong statue","国立ハングル博物館・世宗大王像もどうぞ","也去看看国立韩文博物馆、世宗大王像","也去看看國立韓文博物館、世宗大王像"],
  "메리 크리스마스!": ["Merry Christmas!","メリークリスマス！","圣诞快乐！","聖誕快樂！"],
