  "매달 자동결제로 시작 (월 {price}원)": ["Start monthly plan (KRW {price}/month)", "毎月自動決済で開始（月{price}ウォン）", "开始每月订阅（每月{price}韩元）", "開始每月訂閱（每月{price}韓元）"],
  "1개월 이용권으로 먼저 써 보기 ({price}원)": ["Try a 1-month pass first (KRW {price})", "まずは1か月パスで試す（{price}ウォン）", "先用1个月通行证试试（{price}韩元）", "先用1個月通行證試試（{price}韓元）"],
