  "SK텔레콤 실측 · Plus·Pro 회원 전용": ["SK Telecom measured · Plus/Pro only", "SKテレコム実測・Plus・Pro会員限定", "SK电讯实测 · 仅限Plus/Pro会员", "SK電訊實測 · 僅限Plus/Pro會員"],
  "열어 보기": ["Unlock", "開けてみる", "解锁", "解鎖"],
