  "오늘 {d}회 · 이번 달 {m}회 남음": ["{d} left today · {m} left this month", "今日あと{d}回・今月あと{m}回", "今天剩{d}次 · 本月剩{m}次", "今天剩{d}次 · 本月剩{m}次"],
  "SK텔레콤 실측 · 누를 때 한 번 불러와요": ["SK Telecom measured · Fetched when you tap", "SKテレコム実測・押したときに取得", "SK电讯实测 · 点击时获取", "SK電訊實測 · 點擊時取得"],
  "SK텔레콤 실측 · {time} 기준": ["SK Telecom measured · as of {time}", "SKテレコム実測・{time}時点", "SK电讯实测 · {time}", "SK電訊實測 · {time}"],
  "방금 다른 회원이 본 결과라 횟수가 줄지 않았어요": ["Another member just checked this, so your count wasn't used", "他の会員が直前に見た結果なので回数は減っていません", "这是其他会员刚查看的结果，未扣次数", "這是其他會員剛查看的結果，未扣次數"],
  "오늘 횟수를 다 썼어요": ["You've used all of today's checks", "今日の回数を使い切りました", "今天的次数已用完", "今天的次數已用完"],
  "이번 달 횟수를 다 썼어요": ["You've used all of this month's checks", "今月の回数を使い切りました", "本月次数已用完", "本月次數已用完"],
  "지금은 실제 인원을 불러올 수 없어요": ["Live headcount isn't available right now", "いまは実際の人出を取得できません", "暂时无法获取实时人数", "暫時無法取得即時人數"],
